declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesVO;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesListRef;

trait UserRoleAssignamentRolesAttributeHolder
{
    protected UserRoleAssignamentRolesVO|UserRoleAssignamentRolesListRef| array |null $roles = null;
    protected bool $rolesAssigned = false;

    public function getRolesOrDefault(UserRoleAssignamentRolesVO $roles): UserRoleAssignamentRolesVO
    {
        if ($this->rolesAssigned) {
            $current = UserRoleAssignamentRolesVO::from($this->roles);
            return $current->getWithDefaults($roles) ?? $current;
        } else {
            return $roles;
        }
    }
    public function roles(UserRoleAssignamentRolesVO|UserRoleAssignamentRolesListRef| array |null $roles): static
    {
        $this->roles = $roles;
        $this->rolesAssigned = true;
        return $this;
    }
    public function getRoles(): ?UserRoleAssignamentRolesListRef
    {
        return $this->roles instanceof UserRoleAssignamentRolesVO ? $this->roles->value() : $this->roles;
    }
    public function isRolesAssigned(): bool
    {
        return $this->rolesAssigned;
    }
    public function writeRolesTo(mixed $att): void
    {
        if ($this->rolesAssigned) {
            \assert(null !== $this->roles);
            $att->roles($this->roles);
        }
    }
    public function readRolesFrom(mixed $att): void
    {
        if ($att->isRolesAssigned()) {
            $roles = $att->getRoles();
            \assert(null !== $roles);
            $this->roles($roles);
        }
    }
    public function unsetRoles(): static
    {
        $this->rolesAssigned = false;
        return $this;
    }
    protected function withDefaultRoles(): void
